            aOrbiterB = ((aWandererI + RotL64(aIngress, 47U)) + RotL64(aCarry, 5U)) + 0x0CD97738D3F3AC81ULL;
            aOrbiterD = (aWandererB + RotL64(aScatter, 57U)) + 0x3B5D812056164E4DULL;
            aOrbiterJ = (((aWandererD + RotL64(aCross, 21U)) + RotL64(aCarry, 37U)) + 0xB2FC46B36A18C188ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 11U)) & S_SALT1];
