            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0x5B08A7101F75DACAULL) + aTwistOrbiterUpdateSaltC[((aIndex + 17U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0x96B6B8E25DA4D109ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 28U)) & S_SALT1];
