            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0xBC0E9D80DBE9FAB5ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x1C4FE684A20BC349ULL), 11U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterF) + 0x1B476BC652406D6DULL) + aTwistOrbiterUpdateSaltD[((aIndex + 20U)) & S_SALT1];
