            aOrbiterA = (aWandererD + RotL64(aIngress, 37U)) + 0x8A0E0312DF9A964BULL;
            aOrbiterH = ((aWandererA + RotL64(aScatter, 44U)) + RotL64(aCarry, 53U)) + 0x415C61F237AA58B4ULL;
            aOrbiterB = (aWandererF + RotL64(aCross, 21U)) + 0x032C05D2942444B6ULL;
            aOrbiterK = ((aWandererI + RotL64(aScatter, 57U)) + 0x84B14B8D11EADD28ULL) + aTwistOrbiterAssignSaltE[((aIndex + 14U)) & S_SALT1];
