            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0x7EC8964D832C0C3DULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xB92E141BB47A6CBCULL;
            aOrbiterD = RotL64((aOrbiterD * 0xA5CA9572881D862DULL), 47U);
            //
            aIngress = RotL64(aOrbiterH, 47U) ^ aOrbiterK;
