            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererD = aWandererD + ((((RotL64(aScatter, 11U) + RotL64(aOrbiterC, 37U)) + aOrbiterD) + RotL64(aCarry, 47U)) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 7U)) & S_SALT1]);
