            //
            aOrbiterE = (aWandererE + RotL64(aPrevious, 51U)) + 0x13291C51767278BEULL;
            aOrbiterG = ((aWandererJ + RotL64(aCross, 13U)) + 0x70E02C6F2D4922A7ULL) + aTwistOrbiterAssignSaltC[((aIndex + 7U)) & S_SALT1];
            aOrbiterA = ((aWandererH + RotL64(aScatter, 5U)) + RotL64(aCarry, 23U)) + 0x5D132F69ED59875CULL;
            aOrbiterK = ((aWandererK + RotL64(aIngress, 58U)) + RotL64(aCarry, 47U)) + 0x1F45B983218E6CBCULL;
            aOrbiterI = (aWandererD + RotL64(aScatter, 21U)) + 0xFA376081DFB3B09BULL;
            aOrbiterC = (((aWandererC + RotL64(aCross, 27U)) + RotL64(aCarry, 11U)) + 0xF06A6257D2C3CB2AULL) + aTwistOrbiterAssignSaltD[((aIndex + 5U)) & S_SALT1];
            aOrbiterH = (aWandererI + RotL64(aPrevious, 41U)) + 0xC95A22936F49EA0FULL;
            //
            aOrbiterE = ((aOrbiterE + aOrbiterG) + 0x87EEF266D7B3E890ULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x127A105796B3D590ULL;
