            aOrbiterA = ((aOrbiterA + aOrbiterC) + 0x5F5D3B0F91C506D1ULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterA) ^ 0xFCC6B7AFEEE7B851ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x21F4D137EBA5E76DULL), 51U);
