            aOrbiterH = (aOrbiterH + aOrbiterK) + 0x2E4EBC9F5BEAAB88ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0xC5AA265EAE0AF1F1ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x6D316A8CBAC845F5ULL), 57U);
