            aOrbiterI = ((aOrbiterI + aOrbiterA) + 0xCB959FB598F77A70ULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0xF8BAC306DB6FA935ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x251B838ABDB1C56FULL), 3U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x2BA3AC89E99DCC76ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0xC1137115983C469FULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1738994DB6B2A781ULL), 21U);
