            aOrbiterG = (aOrbiterG + aOrbiterI) + 0xC1A3A2323C27AED7ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x4597811F92A8E454ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x28F7A5D73F5B8F3FULL), 29U);
