            //
            aScatter = (RotL64(aCross, 47U) ^ RotL64(aIngress, 21U)) ^ (RotL64(aPrevious, 35U) + RotL64(aCarry, 4U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterB = ((aWandererJ + RotL64(aPrevious, 13U)) + RotL64(aCarry, 19U)) + 0x315CD84A7A4C782FULL;
            aOrbiterF = ((aWandererC + RotL64(aCross, 29U)) + RotL64(aCarry, 35U)) + 0x0110983737246793ULL;
            aOrbiterI = (aWandererA + RotL64(aScatter, 36U)) + 0x3880A6C75CDB1245ULL;
            aOrbiterD = ((aWandererD + RotL64(aIngress, 47U)) + RotL64(aCarry, 53U)) + 0xA5EAC2E1861A583AULL;
