            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0x8CB9EB9F28D959BDULL) + aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x52CCCAEACBA90A3AULL;
