            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0xEC947C1018B9C0F6ULL) + aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0xB3B477D59D267BEEULL;
            aOrbiterE = RotL64((aOrbiterE * 0x125B3AAEF3AD7F6BULL), 27U);
