            aWandererG = aWandererG + ((((RotL64(aPrevious, 35U) + aOrbiterI) + RotL64(aOrbiterA, 51U)) + RotL64(aCarry, 23U)) + aKeyRotateAWandererUpdateSaltC[((aIndex + 12U)) & S_SALT1]);
