            aWandererK = aWandererK + (((RotL64(aIngress, 11U) + aOrbiterB) + RotL64(aOrbiterC, 5U)) + RotL64(aCarry, 51U));
            aWandererD = aWandererD ^ ((RotL64(aPrevious, 3U) + aOrbiterE) + RotL64(aOrbiterG, 41U));
            aWandererH = aWandererH + (((RotL64(aIngress, 47U) + RotL64(aOrbiterD, 23U)) + aOrbiterE) + aKeyRotateAWandererUpdateSaltF[((aIndex + 21U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aScatter, 58U) + aOrbiterA) + RotL64(aOrbiterE, 47U));
            aWandererJ = aWandererJ + ((RotL64(aCross, 23U) + aOrbiterF) + RotL64(aOrbiterA, 28U));
            aWandererB = aWandererB ^ ((RotL64(aIngress, 41U) + aOrbiterD) + RotL64(aOrbiterH, 37U));
