            aOrbiterE = RotL64((aOrbiterE * 0x4BF9A2864BC795AFULL), 37U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0xF4BF7867AE140D9EULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterI) ^ 0xF69E70221175A3A4ULL) ^ aKeyRotateAOrbiterUpdateSaltE[((aIndex + 17U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x60268ECFE2FD852DULL), 57U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0xB8CA7546D9220A67ULL;
