            aWandererC = aWandererC ^ ((RotL64(aCross, 26U) + RotL64(aOrbiterE, 47U)) + aOrbiterF);
            aWandererI = aWandererI + ((RotL64(aIngress, 39U) + aOrbiterH) + RotL64(aOrbiterJ, 51U));
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 23U) + RotL64(aOrbiterK, 56U)) + aOrbiterA);
            aWandererG = aWandererG + (((RotL64(aCross, 3U) + aOrbiterI) + RotL64(aOrbiterF, 53U)) + aKeyRotateAWandererUpdateSaltF[((aIndex + 7U)) & S_SALT1]);
            //
