            aCross ^= (RotL64(aPlasmaLaneC[((S_BLOCK1 - aIndex + 14806U)) & S_BLOCK1], 30U) ^ RotL64(aPoisonLaneA[((aIndex + 9212U)) & S_BLOCK1], 43U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
