            aScatter = (RotL64(aCarry, 51U) ^ RotL64(aPrevious, 5U)) + (RotL64(aCross, 35U) ^ RotL64(aIngress, 18U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterC = (aWandererJ + RotL64(aIngress, 26U)) + 0x1978C461FC09A8DFULL;
            aOrbiterI = (aWandererA + RotL64(aCross, 11U)) + 0x9A6C928741269EF1ULL;
            aOrbiterH = ((aWandererC + RotL64(aPrevious, 37U)) + 0x57C4D35F6B07D6A8ULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterF = ((aWandererH + RotL64(aScatter, 57U)) + 0x818B21825958355BULL) + aKeyRotateAOrbiterAssignSaltF[((aIndex + 13U)) & S_SALT1];
            aOrbiterK = ((aWandererB + RotL64(aPrevious, 41U)) + RotL64(aCarry, 53U)) + 0x5CF6B63EAB3BA6D1ULL;
            aOrbiterA = ((aWandererF + RotL64(aScatter, 35U)) + RotL64(aCarry, 23U)) + 0xD90E39641C9692DAULL;
            aOrbiterE = (aWandererK + RotL64(aIngress, 60U)) + 0xC1DCC8225E74C1CCULL;
            aOrbiterB = ((aWandererI + RotL64(aCross, 3U)) + RotL64(aCarry, 41U)) + 0x2DD39FD40FE882C8ULL;
            aOrbiterD = (aWandererD + RotL64(aScatter, 51U)) + 0x69A09941930C41FCULL;
            aOrbiterG = (aWandererE + RotL64(aCross, 39U)) + 0x40CD7C1BF41C4AAFULL;
            aOrbiterJ = (aWandererG + RotL64(aIngress, 19U)) + 0x21A2542A654C59C7ULL;
