            aOrbiterA = ((aOrbiterA ^ aOrbiterB) ^ 0x74E78961CD1BBD0BULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 28U)) & S_SALT1];
