            aWandererG = aWandererG + (((RotL64(aPrevious, 36U) + aOrbiterA) + RotL64(aOrbiterC, 11U)) + aKeyRotateAWandererUpdateSaltA[((aIndex + 24U)) & S_SALT1]);
