            //
            aOrbiterD = ((aWandererC + RotL64(aCross, 53U)) + RotL64(aCarry, 41U)) + 0xE1540AB017ADE026ULL;
            aOrbiterK = ((aWandererE + RotL64(aScatter, 27U)) + 0xAF70D6B0537E2BE5ULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
