            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x141AFEACA1631351ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterG) ^ 0x66DA93AB17BF4736ULL) ^ aKeyRotateAOrbiterUpdateSaltE[((aIndex + 23U)) & S_SALT1];
